const body = $input.first()?.json?.body ?? $input.first()?.json ?? {};
const collection = body.collection || 'portfolio';
const defaultDocs = [
  {
    title: '프로필 및 아키텍처 철학',
    category: 'profile',
    content: 'shnea: 풀스택 엔지니어 겸 AI 에이전트 시스템 아키텍트. 뇌대리, Jjapgma, Voxtune, 끄적 등 다중 에이전트 및 미디어 파이프라인 구축. 모듈화된 파이프라인과 신뢰성 높은 자동화 추구.'
  },
  {
    title: '프로젝트 · 뇌대리 (Noedaeri)',
    category: 'projects',
    content: '뇌대리: 플랫폼과 외부 서비스(블로그, 포트폴리오, UI 빌더 등)의 고자원 AI 연산과 미디어 변환(FFmpeg HLS/썸네일, TTS, 임베딩)을 중계·관리하는 고성능 에이전트 시스템. Raya 난이도 라우팅(L1/L2/L3)과 n8n AI 에이전트 워크플로를 연동.'
  },
  {
    title: '프로젝트 · Jjapgma (플랫폼 UI 빌더)',
    category: 'projects',
    content: 'Jjapgma: 컴포넌트 레지스트리, 템플릿, 반응형 디자인 토큰 및 MCP(Model Context Protocol)를 결합하여 사람과 AI가 동일한 캔버스 설계를 다룰 수 있는 웹 UI 플랫폼.'
  },
  {
    title: '프로젝트 · Voxtune',
    category: 'projects',
    content: 'Voxtune: 음악 오디오 생성 및 보컬 튜닝, 오디오 후처리 파이프라인 서비스. 백엔드, 오디오 워커, PostgreSQL, Redis 연동 기반.'
  },
  {
    title: '기술 스택',
    category: 'tech_stack',
    content: '주요 언어 및 기술: Python (FastAPI, Pytest), TypeScript/JavaScript (Node.js, React, Next.js), n8n (LangChain 에이전트/RAG 파이프라인), PostgreSQL (17), Docker, FFmpeg, SOPS+age 환경 암호화 관리.'
  }
];

const docs = Array.isArray(body.documents) && body.documents.length > 0 ? body.documents : defaultDocs;

return docs.map(d => ({
  json: {
    collection: collection,
    text: d.text || `[${d.category || 'general'}] ${d.title || ''}\n${d.content || ''}`,
    metadata: {
      title: d.title || '',
      category: d.category || '',
      collection: collection,
      ...(d.metadata || {})
    }
  }
}));

const items = $input.all();
const collection = items[0]?.json?.collection || 'portfolio';
return [{
  json: {
    status: 'success',
    message: `${collection} 데이터 벡터 인덱싱 완료`,
    collection: collection,
    chunk_count: items.length,
    timestamp: new Date().toISOString()
  }
}];
